from fastapi import FastAPI, Form, File, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test-form-file")
async def test_form_file(a: str = Form(...), b: UploadFile = File(...)):
    return {"a": a, "b": b.filename}

@app.post("/test-file-form")
async def test_file_form(b: UploadFile = File(...), a: str = Form(...)):
    return {"a": a, "b": b.filename}

client = TestClient(app)

def test_form_then_file():
    files = {"b": ("filename.txt", b"content")}
    data = {"a": "hello"}
    response = client.post("/test-form-file", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"a": "hello", "b": "filename.txt"}

def test_file_then_form():
    files = {"b": ("filename.txt", b"content")}
    data = {"a": "hello"}
    response = client.post("/test-file-form", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"a": "hello", "b": "filename.txt"}

if __name__ == "__main__":
    import pytest
    # This is a simple script to run tests. In a real scenario, use pytest.
    try:
        test_form_then_file()
        test_file_then_form()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
